def format_and_log_error(
    step_name: str,
    e: Exception
) -> str:
    try:
        message = (
            f"[{step_name}] {type(e).__name__}: {e}"
        )[:800]
    except Exception:
        message = (
            f"[{step_name}] {type(e).__name__}: "
            "Unable to format exception"
        )[:800]

    try:
        logError(message)
    except Exception as logging_error:
        print(f"Error logging failed: {logging_error}")
        print(message)

    return message

def load_entities(entities_json: str) -> list:
    orchestration_path = (
        f"abfss://odw-config@{storage_account}"
        "orchestration/orchestration_service_bus.json"
    )

    config_row = (
        spark.read
        .text(orchestration_path, wholetext=True)
        .first()
    )

    if config_row is None:
        raise ValueError("Orchestration configuration is empty")

    orchestration = json.loads(config_row["value"])

    if not isinstance(orchestration, dict):
        raise ValueError(
            "Orchestration configuration must be an object"
        )

    config_entities = orchestration.get("entities")

    if not isinstance(config_entities, list):
        raise ValueError(
            "Orchestration 'entities' must be a list"
        )

    enabled_entities = []

    for entity in config_entities:
        if not isinstance(entity, dict):
            raise ValueError(
                "Every orchestration entity must be an object"
            )

        if (
            entity.get("processing_enabled") is True
            and entity.get("run_raw_to_std") is True
        ):
            name = entity.get("entity_name")

            if not isinstance(name, str) or not name.strip():
                raise ValueError(
                    "Enabled entity has missing entity_name"
                )

            enabled_entities.append(entity)

    lookup = {
        entity["entity_name"]: entity
        for entity in enabled_entities
    }

    if len(lookup) != len(enabled_entities):
        raise ValueError(
            "Duplicate enabled entity names in orchestration"
        )

    if not entities_json or not entities_json.strip():
        return enabled_entities

    selected_names = json.loads(entities_json)

    if not isinstance(selected_names, list) or not all(
        isinstance(name, str) and name.strip()
        for name in selected_names
    ):
        raise ValueError(
            "entities_json must be a JSON array of entity names"
        )

    if len(set(selected_names)) != len(selected_names):
        raise ValueError(
            "entities_json contains duplicate entity names"
        )

    missing = [
        name for name in selected_names
        if name not in lookup
    ]

    if missing:
        raise ValueError(
            f"Entities missing or disabled in orchestration: {missing}"
        )

    return [lookup[name] for name in selected_names]


try:
    entities = load_entities(entities_json)
    print(f"Found {len(entities)} entities to process")

except Exception as e:
    format_and_log_error("Load orchestration entities", e)
    raise

def create_spark_schema(entity_name: str):
    output = mssparkutils.notebook.run(
        "/py_create_spark_schema",
        30,
        {
            "db_name": "odw_standardised_db",
            "entity_name": entity_name
        }
    )

    payload = json.loads(output) if output else {}
    schema_value = payload.get("schema")

    if not schema_value:
        return None

    if isinstance(schema_value, str):
        schema_value = json.loads(schema_value)

    return StructType.fromJson(schema_value)

def read_raw_messages(
    source_path: str,
    last_ingest_time,
    entity_name: str,
    spark_schema
) -> DataFrame:
    reader = (
        spark.read
        .option("multiline", "true")
        .option("recursiveFileLookup", "true")
    )

    file_filter_enabled = (
        ENABLE_FILE_FILTER_ENTITIES is None
        or entity_name in ENABLE_FILE_FILTER_ENTITIES
    )

    if last_ingest_time and file_filter_enabled:
        try:
            watermark_dt = datetime.fromisoformat(
                str(last_ingest_time).replace("Z", "+00:00")
            )

            modified_after = (
                watermark_dt - timedelta(days=1)
            ).strftime("%Y-%m-%dT%H:%M:%S")

            reader = reader.option(
                "modifiedAfter",
                modified_after
            )

        except ValueError as parse_error:
            print(
                f"Skipping file-level filter for {entity_name}: "
                f"{parse_error}"
            )

    if spark_schema is not None:
        reader = reader.schema(spark_schema)

    return reader.json(source_path)

def prepare_messages(
    df: DataFrame,
    last_ingest_time,
    watermark_column: str
) -> DataFrame:
    if watermark_column not in df.columns:
        raise ValueError(
            f"Missing watermark column: {watermark_column}"
        )

    if last_ingest_time:
        df = df.filter(
            F.col(watermark_column).cast("timestamp")
            > F.lit(last_ingest_time).cast("timestamp")
        )

    return df.withColumns({
        "expected_from": F.current_timestamp(),
        "expected_to": F.expr(
            "current_timestamp() + INTERVAL 1 DAY"
        ),
        "ingested_datetime": (
            F.col(watermark_column).cast("timestamp")
        ),
        "input_file": F.input_file_name()

def dedupe_dataframe(df: DataFrame) -> DataFrame:
    excluded_columns = {
        "expected_to",
        "expected_from",
        "ingested_datetime"
    }

    dedupe_columns = [
        column
        for column in df.columns
        if column not in excluded_columns
    ]

    return (
        df.dropDuplicates(dedupe_columns)
        if dedupe_columns
        else df

def apply_anonymisation_sb(
    df: DataFrame,
    entity_name: str
) -> DataFrame:
    if not Util.is_non_production_environment():
        return df

    anon_config = AnonymisationConfig()

    try:
        policy_path = (
            f"abfss://odw-config@{storage_account}"
            "anonymisation/policy.yaml"
        )

        policy_row = (
            spark.read
            .text(policy_path, wholetext=True)
            .first()
        )

        if policy_row is None:
            raise ValueError("Anonymisation policy is empty")

        anon_config = load_config(
            text=policy_row["value"]
        )

    except Exception as config_error:
        print(
            f"Using default anonymisation config for "
            f"{entity_name}: {config_error}"
        )

    engine = AnonymisationEngine(
        config=AnonymisationConfig(
            classification_allowlist=(
                anon_config.classification_allowlist
            ),
            seed_column=anon_config.get_seed_column(
                entity_name
            )
        )
    )

    return engine.apply_from_purview(
        df,
        entity_name=entity_name,
        source_folder="ServiceBus"
